<template>
  <div class="container">
    <header class="page-header">
      <h1>YOLO黄瓜检测</h1>
      <p class="header-subtitle">支持图片上传、文件夹批量上传和摄像头实时检测</p>
    </header>
    
    <main class="content-wrapper">
      <!-- 检测方式选择 -->
      <div class="detection-mode-selector">
        <button 
          class="mode-btn" 
          :class="{ 'active': detectionMode === 'upload' }"
          @click="setDetectionMode('upload')"
        >
          <i class="fas fa-upload"></i> 图片上传
        </button>
        <button 
          class="mode-btn" 
          :class="{ 'active': detectionMode === 'folder' }"
          @click="setDetectionMode('folder')"
        >
          <i class="fas fa-folder-open"></i> 文件夹上传
        </button>
        <button 
          class="mode-btn" 
          :class="{ 'active': detectionMode === 'camera' }"
          @click="setDetectionMode('camera')"
        >
          <i class="fas fa-video"></i> 摄像头检测
        </button>
      </div>
      
      <!-- 单图片上传区域 -->
      <section class="card upload-section" v-if="detectionMode === 'upload'">
        <div class="card-header">
          <h2>图片上传</h2>
        </div>
        <div class="card-body">
          <form @submit.prevent="handleSubmit" class="upload-form">
            <label for="imageInput" class="file-label">
              <span class="file-icon">
                <i class="fas fa-upload"></i>
              </span>
              <span class="file-text" v-if="!imageFile">点击或拖拽图片到此处上传</span>
              <span class="file-text" v-if="imageFile">{{ imageFile.name }}</span>
              <input 
                type="file" 
                id="imageInput" 
                name="image" 
                accept="image/*" 
                required
                @change="handleImageChange"
                class="file-input"
              >
            </label>
            <button type="submit" class="btn btn-primary upload-btn" :disabled="!imageFile || isLoading">
              <span v-if="!isLoading">上传并检测</span>
              <span v-if="isLoading">
                <i class="fas fa-spinner fa-spin"></i> 处理中...
              </span>
            </button>
          </form>
          
          <!-- 预览图 -->
          <div v-if="imagePreviewUrl" class="image-preview-container">
            <h3 class="preview-title">预览图</h3>
            <img 
              :src="imagePreviewUrl" 
              alt="预览图" 
              class="image-preview"
            >
          </div>
        </div>
      </section>

      <!-- 文件夹上传区域 -->
      <section class="card folder-section" v-if="detectionMode === 'folder'">
        <div class="card-header">
          <h2>文件夹批量上传</h2>
        </div>
        <div class="card-body">
          <div class="folder-upload-container">
            <label for="folderInput" class="folder-label">
              <span class="folder-icon">
                <i class="fas fa-folder-open"></i>
              </span>
              <span class="folder-text" v-if="folderFiles.length === 0">点击或拖拽文件夹到此处上传</span>
              <div v-if="folderFiles.length > 0" class="folder-files-info">
                <p>已选择 {{ folderFiles.length }} 个图片文件</p>
                <div class="files-list">
                  <div v-for="(file, index) in folderFiles" :key="index" class="file-item">
                    <i class="fas fa-file-image"></i>
                    <span class="file-name">{{ file.name }}</span>
                    <button 
                      class="remove-file-btn" 
                      @click.stop="removeFile(index)"
                      title="移除文件"
                    >
                      <i class="fas fa-times"></i>
                    </button>
                  </div>
                </div>
              </div>
              <input 
                type="file" 
                id="folderInput" 
                webkitdirectory 
                directory 
                accept="image/*" 
                @change="handleFolderChange"
                class="folder-input"
              >
            </label>
            
            <div class="folder-actions">
              <button 
                class="btn btn-primary process-folder-btn" 
                @click="processFolder"
                :disabled="folderFiles.length === 0 || isLoading || isProcessing"
              >
                <span v-if="!isProcessing">批量检测 ({{ folderFiles.length }})</span>
                <span v-if="isProcessing">
                  <i class="fas fa-spinner fa-spin"></i> 处理中 ({{ processedCount }}/{{ folderFiles.length }})
                </span>
              </button>
              <button 
                class="btn btn-secondary clear-folder-btn" 
                @click="clearFolder"
                :disabled="folderFiles.length === 0 || isProcessing"
              >
                <i class="fas fa-trash"></i> 清空列表
              </button>
            </div>
          </div>
          
          <!-- 批量处理进度 -->
          <div v-if="isProcessing" class="processing-progress">
            <div class="progress-bar" :style="{ width: progressPercentage + '%' }"></div>
          </div>
        </div>
      </section>

      <!-- 摄像头区域 -->
      <section class="card camera-section" v-if="detectionMode === 'camera'">
        <div class="card-header">
          <h2>摄像头实时检测</h2>
        </div>
        <div class="card-body">
          <div class="camera-container">
            <!-- 摄像头视频流 -->
            <div class="camera-preview-wrapper">
              <video 
                id="cameraPreview" 
                class="camera-preview" 
                autoplay 
                playsinline
                ref="videoRef"
              ></video>
              <canvas 
                id="detectionCanvas" 
                class="detection-canvas"
                ref="canvasRef"
              ></canvas>
            </div>
            
            <!-- 摄像头控制按钮 -->
            <div class="camera-controls">
              <button 
                class="btn btn-primary start-camera-btn" 
                @click="startCamera"
                :disabled="isCameraActive || isLoading"
              >
                <i class="fas fa-play"></i> 启动摄像头
              </button>
              <button 
                class="btn btn-danger stop-camera-btn" 
                @click="stopCamera"
                :disabled="!isCameraActive"
              >
                <i class="fas fa-stop"></i> 停止摄像头
              </button>
              <button 
                class="btn btn-secondary toggle-detection-btn" 
                @click="toggleDetection"
                :disabled="!isCameraActive"
              >
                <i v-if="isDetecting" class="fas fa-pause"></i>
                <i v-if="!isDetecting" class="fas fa-play"></i>
                {{ isDetecting ? '暂停检测' : '开始检测' }}
              </button>
            </div>
          </div>
        </div>
      </section>

      <!-- 结果区域 -->
      <section class="card results-section">
        <div class="card-header">
          <h2>检测结果</h2>
        </div>
        <div class="card-body">
          <div id="detectionResults" class="results-content">
            <!-- 加载状态 -->
            <div v-if="isLoading" class="status-indicator loading">
              <i class="fas fa-circle-notch fa-spin"></i>
              <p>正在检测中，请稍候...</p>
            </div>
            
            <!-- 错误信息 -->
            <div v-if="errorMessage" class="status-indicator error">
              <i class="fas fa-exclamation-circle"></i>
              <p>{{ errorMessage }}</p>
            </div>
            
            <!-- 单图检测结果列表 -->
            <div v-if="detections.length > 0 && !isLoading && !errorMessage && !isBatchMode" class="detections-list">
              <p class="results-summary">检测到 <span class="count">{{ detections.length }}</span> 个黄瓜：</p>
              <ul>
                <li v-for="(obj, index) in detections" :key="index" class="detection-item">
                  <div class="detection-class">{{ obj.class }}</div>
                  <div class="detection-meta">
                    <span class="confidence">置信度：{{ obj.confidence.toFixed(2) }}</span>
                    <span class="position">位置：{{ formatBox(obj.box) }}</span>
                  </div>
                </li>
              </ul>
            </div>
            
            <!-- 批量检测结果列表 -->
            <div v-if="batchResults.length > 0 && !isLoading && !errorMessage && isBatchMode" class="batch-results-list">
              <p class="results-summary">批量检测结果 ({{ processedCount }}/{{ folderFiles.length }})：</p>
              <div class="batch-results-container">
                <div v-for="(result, index) in batchResults" :key="index" class="batch-result-item">
                  <div class="result-header">
                    <h4>{{ result.filename }}</h4>
                    <span class="result-count">检测到 {{ result.detections.length }} 个黄瓜</span>
                  </div>
                  <div class="result-content">
                    <img 
                      :src="result.previewUrl" 
                      class="batch-result-preview" 
                      alt="检测结果预览"
                    >
                    <ul class="batch-detections-list">
                      <li v-for="(obj, i) in result.detections" :key="i" class="batch-detection-item">
                        <span class="detection-class">{{ obj.class }}</span>
                        <span class="detection-confidence">置信度：{{ obj.confidence.toFixed(2) }}</span>
                      </li>
                    </ul>
                  </div>
                </div>
              </div>
            </div>
            
            <!-- 无结果状态 -->
            <div v-if="detections.length === 0 && !isLoading && !errorMessage && hasResults && !isBatchMode" class="status-indicator empty">
              <i class="fas fa-search"></i>
              <p>未检测到黄瓜</p>
            </div>
            
            <!-- 摄像头未启动提示 -->
            <div v-if="detectionMode === 'camera' && !isCameraActive && !isLoading && !errorMessage && !hasResults" class="status-indicator info">
              <i class="fas fa-info-circle"></i>
              <p>请点击"启动摄像头"开始实时检测</p>
            </div>
            
            <!-- 文件夹未选择提示 -->
            <div v-if="detectionMode === 'folder' && folderFiles.length === 0 && !isLoading && !errorMessage && !hasResults" class="status-indicator info">
              <i class="fas fa-info-circle"></i>
              <p>请选择包含图片的文件夹进行批量检测</p>
            </div>
          </div>
          
          <!-- 标注后的图片 (单图上传模式) -->
          <div v-if="annotatedImageUrl && !isLoading && !errorMessage && detectionMode === 'upload'" class="result-image-container">
            <h3 class="result-image-title">标注结果图</h3>
            <img 
              :src="annotatedImageUrl" 
              class="result-image" 
              alt="检测结果图片"
            >
          </div>
        </div>
      </section>
    </main>
    
    <footer class="page-footer">
      <p>YOLO黄瓜检测系统 &copy; 2025</p>
    </footer>
  </div>
</template>

<script setup>
import { ref, onMounted, onUnmounted, nextTick } from 'vue';

// 状态管理
const imageFile = ref(null);
const imagePreviewUrl = ref('');
const detections = ref([]);
const annotatedImageUrl = ref('');
const isLoading = ref(false);
const errorMessage = ref('');
const hasResults = ref(false);
const detectionMode = ref('upload'); // 'upload', 'folder' 或 'camera'

// 文件夹批量上传相关状态
const folderFiles = ref([]);
const isProcessing = ref(false);
const processedCount = ref(0);
const progressPercentage = ref(0);
const batchResults = ref([]);
const isBatchMode = ref(false);

// 摄像头相关状态
const videoRef = ref(null);
const canvasRef = ref(null);
const isCameraActive = ref(false);
const isDetecting = ref(false);
const detectionInterval = ref(null);
const streamRef = ref(null);

// 切换检测模式
const setDetectionMode = (mode) => {
  // 切换模式时停止摄像头和检测
  if (mode !== detectionMode.value) {
    stopCamera();
    detectionMode.value = mode;
    resetResults();
    
    // 重置批量处理状态
    if (mode !== 'folder') {
      isBatchMode.value = false;
    }
  }
};

// 处理单张图片选择
const handleImageChange = (e) => {
  const file = e.target.files[0];
  if (file) {
    imageFile.value = file;
    // 生成预览图
    const reader = new FileReader();
    reader.onload = (event) => {
      imagePreviewUrl.value = event.target.result;
    };
    reader.readAsDataURL(file);
  }
};

// 处理文件夹选择
const handleFolderChange = (e) => {
  const files = Array.from(e.target.files);
  if (files.length > 0) {
    // 过滤出图片文件
    const imageFiles = files.filter(file => file.type.startsWith('image/'));
    
    // 为每个文件生成预览
    imageFiles.forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        file.previewUrl = event.target.result;
        folderFiles.value.push(file);
      };
      reader.readAsDataURL(file);
    });
  }
  // 重置输入以允许重新选择同一文件夹
  e.target.value = '';
};

// 移除单个文件
const removeFile = (index) => {
  folderFiles.value.splice(index, 1);
};

// 清空文件夹列表
const clearFolder = () => {
  folderFiles.value = [];
  batchResults.value = [];
  processedCount.value = 0;
  progressPercentage.value = 0;
};

// 处理文件夹批量检测
const processFolder = async () => {
  if (folderFiles.value.length === 0) return;
  
  // 重置状态
  isProcessing.value = true;
  isLoading.value = true;
  isBatchMode.value = true;
  errorMessage.value = '';
  batchResults.value = [];
  processedCount.value = 0;
  progressPercentage.value = 0;
  hasResults.value = true;
  
  try {
    // 逐个处理文件
    for (let i = 0; i < folderFiles.value.length; i++) {
      const file = folderFiles.value[i];
      
      // 跳过非图片文件
      if (!file.type.startsWith('image/')) {
        processedCount.value++;
        progressPercentage.value = Math.round((processedCount.value / folderFiles.value.length) * 100);
        continue;
      }
      
      // 创建FormData并发送请求
      const formData = new FormData();
      formData.append('image', file);
      
      const response = await fetch('https://123.56.203.202/detect', {
        method: 'POST',
        body: formData
      });
      
      if (!response.ok) {
        throw new Error(`处理第 ${i+1} 个文件时出错，HTTP状态码：${response.status}`);
      }
      
      const data = await response.json();
      
      if (data.error) {
        throw new Error(`处理第 ${i+1} 个文件时出错：${data.error}`);
      }
      
      // 保存结果
      batchResults.value.push({
        filename: file.name,
        detections: data.detections || [],
        previewUrl: file.previewUrl,
        annotatedUrl: data.annotated_image ? `data:image/jpg;base64,${data.annotated_image}` : null
      });
      
      // 更新进度
      processedCount.value++;
      progressPercentage.value = Math.round((processedCount.value / folderFiles.value.length) * 100);
      
      // 每处理一个文件后短暂延迟，避免请求过于密集
      if (i < folderFiles.value.length - 1) {
        await new Promise(resolve => setTimeout(resolve, 500));
      }
    }
    
  } catch (error) {
    errorMessage.value = `批量处理错误：${error.message}`;
    console.error('批量检测失败：', error);
  } finally {
    isProcessing.value = false;
    isLoading.value = false;
  }
};

// 格式化边界框显示
const formatBox = (box) => {
  return box.map(coord => coord.toFixed(2)).join(', ');
};

// 重置结果状态
const resetResults = () => {
  detections.value = [];
  annotatedImageUrl.value = '';
  errorMessage.value = '';
  hasResults.value = false;
  batchResults.value = [];
  processedCount.value = 0;
  progressPercentage.value = 0;
};

// 处理单张图片上传检测
const handleSubmit = async () => {
  if (!imageFile.value) return;
  
  // 重置状态
  isLoading.value = true;
  resetResults();
  isBatchMode.value = false;
  
  try {
    const formData = new FormData();
    formData.append('image', imageFile.value);
    
    const response = await fetch('https://123.56.203.202/detect', {
      method: 'POST',
      body: formData
    });

    if (!response.ok) {
      throw new Error(`HTTP错误！状态码：${response.status}`);
    }

    const data = await response.json();
    
    if (data.error) {
      throw new Error(data.error);
    }
    
    // 更新状态
    hasResults.value = true;
    detections.value = data.detections || [];
    
    // 显示标注后的图片
    if (data.annotated_image) {
      annotatedImageUrl.value = `data:image/jpg;base64,${data.annotated_image}`;
    }

  } catch (error) {
    errorMessage.value = `错误：${error.message}`;
    console.error('检测失败：', error);
  } finally {
    isLoading.value = false;
  }
};

// 启动摄像头
const startCamera = async () => {
  try {
    // 请求摄像头权限
    streamRef.value = await navigator.mediaDevices.getUserMedia({ 
      video: { 
        width: { ideal: 1280 },
        height: { ideal: 720 },
        facingMode: 'environment' // 优先使用后置摄像头
      } 
    });
    
    // 等待DOM更新
    await nextTick();
    
    // 设置视频源
    if (videoRef.value) {
      videoRef.value.srcObject = streamRef.value;
      
      // 视频加载完成后设置canvas尺寸
      videoRef.value.onloadedmetadata = () => {
        if (canvasRef.value) {
          canvasRef.value.width = videoRef.value.videoWidth;
          canvasRef.value.height = videoRef.value.videoHeight;
        }
      };
    }
    
    isCameraActive.value = true;
    errorMessage.value = '';
  } catch (error) {
    console.error('启动摄像头失败：', error);
    errorMessage.value = `摄像头启动失败：${error.message}`;
    isCameraActive.value = false;
  }
};

// 停止摄像头
const stopCamera = () => {
  if (streamRef.value) {
    streamRef.value.getTracks().forEach(track => track.stop());
    streamRef.value = null;
  }
  
  if (videoRef.value) {
    videoRef.value.srcObject = null;
  }
  
  // 停止检测
  toggleDetection(false);
  
  isCameraActive.value = false;
  resetResults();
};

// 切换检测状态
const toggleDetection = (forceState = null) => {
  // 强制设置状态（用于停止摄像头时）
  const newState = forceState !== null ? forceState : !isDetecting.value;
  
  if (newState && !isDetecting.value) {
    // 开始检测
    isDetecting.value = true;
    hasResults.value = true;
    isBatchMode.value = false;
    // 立即执行一次检测
    detectFromCamera();
    // 设置轮询检测（每2秒一次，可根据性能调整）
    detectionInterval.value = setInterval(detectFromCamera, 2000);
  } else if (!newState && isDetecting.value) {
    // 停止检测
    isDetecting.value = false;
    if (detectionInterval.value) {
      clearInterval(detectionInterval.value);
      detectionInterval.value = null;
    }
  }
};

// 从摄像头捕获帧并检测
const detectFromCamera = async () => {
  if (!isCameraActive.value || !videoRef.value || !canvasRef.value) return;
  
  // 避免上一次检测未完成时再次发起请求
  if (isLoading.value) return;
  
  try {
    isLoading.value = true;
    
    // 绘制当前视频帧到canvas
    const ctx = canvasRef.value.getContext('2d');
    ctx.drawImage(
      videoRef.value, 
      0, 0, 
      canvasRef.value.width, 
      canvasRef.value.height
    );
    
    // 将canvas内容转为Blob
    canvasRef.value.toBlob(async (blob) => {
      if (!blob) throw new Error('无法从摄像头捕获图像');
      
      // 创建FormData并发送请求
      const formData = new FormData();
      formData.append('image', blob, 'camera-frame.jpg');
      
      const response = await fetch('https://123.56.203.202/detect', {
        method: 'POST',
        body: formData
      });
      
      if (!response.ok) {
        throw new Error(`HTTP错误！状态码：${response.status}`);
      }
      
      const data = await response.json();
      
      if (data.error) {
        throw new Error(data.error);
      }
      
      // 更新检测结果
      detections.value = data.detections || [];
      
      // 绘制检测框到canvas
      drawDetectionBoxes(detections.value);
      
    }, 'image/jpeg');
    
  } catch (error) {
    errorMessage.value = `检测错误：${error.message}`;
    console.error('摄像头检测失败：', error);
  } finally {
    isLoading.value = false;
  }
};

// 在canvas上绘制检测框
const drawDetectionBoxes = (detections) => {
  if (!canvasRef.value || !videoRef.value) return;
  
  const canvas = canvasRef.value;
  const ctx = canvas.getContext('2d');
  const videoWidth = videoRef.value.videoWidth;
  const videoHeight = videoRef.value.videoHeight;
  
  // 清除之前的绘制
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  
  // 重新绘制当前帧作为背景
  ctx.drawImage(videoRef.value, 0, 0, canvas.width, canvas.height);
  
  // 绘制每个检测到的对象
  detections.forEach(obj => {
    // 边界框坐标 (x1, y1, x2, y2)
    const [x1, y1, x2, y2] = obj.box;
    
    // 绘制矩形框
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.strokeRect(x1, y1, x2 - x1, y2 - y1);
    
    // 绘制标签背景
    ctx.fillStyle = '#3b82f6';
    const label = `${obj.class} (${obj.confidence.toFixed(2)})`;
    const textMetrics = ctx.measureText(label);
    ctx.fillRect(
      x1, 
      y1 - 20, 
      textMetrics.width + 10, 
      20
    );
    
    // 绘制标签文本
    ctx.fillStyle = 'white';
    ctx.font = '14px Arial';
    ctx.fillText(label, x1 + 5, y1 - 5);
  });
};

// 组件卸载时清理
onUnmounted(() => {
  stopCamera();
});
</script>

<style scoped>
/* 全局样式 */
.container {
  font-family: 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  max-width: 1000px;
  margin: 0 auto;
  padding: 20px;
  background-color: #f8fafc;
  min-height: 100vh;
  box-sizing: border-box;
}

/* 页面头部 */
.page-header {
  text-align: center;
  margin-bottom: 30px;
  padding-bottom: 20px;
  border-bottom: 1px solid #e2e8f0;
}

.page-header h1 {
  color: #1e293b;
  font-size: 2.2rem;
  margin-bottom: 10px;
  font-weight: 700;
}

.header-subtitle {
  color: #64748b;
  font-size: 1.1rem;
  margin: 0;
}

/* 检测模式选择器 */
.detection-mode-selector {
  display: flex;
